/* Optional appearance preferences, separate from library data and status semantics. */
const Personalization=(()=>{
 const KEY='anishelf-personalization-v1',tiers=['page','sidebar','control','flyout','drawer'];
 const defaults={page:{blur:16,opacity:85},sidebar:{blur:16,opacity:80},control:{blur:10,opacity:80},flyout:{blur:20,opacity:90},drawer:{blur:20,opacity:90}};
 const labels={title:['个性化','Personalization'],reset:['恢复默认','Restore default'],all:['恢复全部个性化默认设置','Reset all personalization'],background:['应用背景','App background'],backgroundHelp:['选择本地 PNG、JPEG 或 WebP 图片；深色模式自动调暗。图片保存在当前资料库。','Choose a local PNG, JPEG or WebP image. Dark mode dims it automatically. The image stays in the selected data store.'],choose:['选择图片','Choose image'],none:['未设置背景','No background image'],ready:['已设置背景','Background image set'],accent:['UI 主题色','UI accent color'],accentHelp:['应用于导航、按钮和焦点；观看状态和统计状态颜色保持独立。为保证文字对比度，明暗模式自动调整颜色明度。','Used for navigation, buttons and focus. Watch status and statistics colors stay independent. Brightness adapts to light and dark modes for readable text.'],page:['主页面背景层','Main page backdrop'],pageHelp:['Watching、My Library、Favorites、片单、统计与设置页面和应用背景之间的毛玻璃层。只模糊后方背景，不模糊海报或文字。','A frosted layer between the app background and Watching, My Library, Favorites, lists, Statistics and Settings. Only the background is blurred; posters and text stay clear.'],sidebar:['侧边栏','Sidebar'],sidebarHelp:['左侧导航栏的背景，包括展开和收起状态。独立于主页面背景层，文字与图标保持清晰。','The left navigation background, expanded or collapsed. Independent of the main page backdrop; text and icons stay clear.'],control:['控件与工具栏','Controls and toolbars'],controlHelp:['搜索、主要按钮、筛选栏、日期条带与片单操作。各控件保留少量透明度差异；输入与文字框由弹窗与临时浮层调节。','Search, action buttons, filters, date strip and list actions. Controls retain slight opacity differences; input and text boxes use Dialogs and flyouts.'],flyout:['弹窗与临时浮层','Dialogs and flyouts'],flyoutHelp:['添加动漫、随机抽取、片单管理、下拉菜单、通知，以及详情中的输入与文字框、设置分组框。','Add Anime, Shuffle, list management, dropdown menus, notifications, details input and text boxes, and settings groups.'],drawer:['动漫详情底板','Anime details panel'],drawerHelp:['右侧详情面板的底板；其中的输入与文字框由弹窗与临时浮层调节。','The right details panel surface. Its input and text boxes use Dialogs and flyouts.'],blur:['背景模糊','Background blur'],opacity:['不透明度基准','Base opacity'],help:['调节后立即生效。较低不透明度可能降低复杂背景上的文字可读性；高对比或减少透明度模式优先使用实色。','Changes apply immediately. Lower opacity may reduce legibility over busy backgrounds. High contrast and reduced transparency use solid surfaces.'],error:['无法保存个性化设置，浏览器存储空间可能已满。','Could not save appearance settings. Browser storage may be full.'],imageError:['请选择不超过 15 MB 的 PNG、JPEG 或 WebP 图片。','Choose a PNG, JPEG or WebP image no larger than 15 MB.'],loadError:['无法读取这张图片，请换一张图片。','Could not read this image. Please choose another.']};
 const text=key=>labels[key][I18n.getLanguage()==='en-US'?1:0];
 const clamp=(n,min,max,fallback)=>typeof n==='number'&&Number.isFinite(n)?Math.round(Math.min(max,Math.max(min,n))):fallback;
 function normalize(raw){const out={};if(!raw||typeof raw!=='object')return out;
  if(/^#[0-9a-f]{6}$/i.test(raw.accent||''))out.accent=raw.accent.toLowerCase();
  if(typeof raw.background==='string'&&raw.background.length<=3000000&&/^data:image\/(jpeg|png|webp);base64,[a-z0-9+/=]+$/i.test(raw.background))out.background=raw.background;
  tiers.forEach(k=>{if(raw[k]&&typeof raw[k]==='object')out[k]={blur:clamp(raw[k].blur,0,30,defaults[k].blur),opacity:clamp(raw[k].opacity,40,100,defaults[k].opacity)}});return out;
 }
 let config={};try{config=normalize(JSON.parse(AppStorage.getItem(KEY)||'{}'))}catch{}
 let imageGeneration=0,persisted=config;
 const rgb=hex=>[1,3,5].map(i=>parseInt(hex.slice(i,i+2),16));
 const hex=values=>'#'+values.map(n=>Math.round(n).toString(16).padStart(2,'0')).join('');
 const mix=(a,b,amount)=>a.map((n,i)=>n+(b[i]-n)*amount);
 function luminance(c){return c.map(n=>{n/=255;return n<=.04045?n/12.92:((n+.055)/1.055)**2.4}).reduce((sum,n,i)=>sum+n*[.2126,.7152,.0722][i],0)}
 function palette(color,dark){let c=rgb(color),target=dark?[255,255,255]:[0,0,0];while(dark?luminance(c)<.52:luminance(c)>.12)c=mix(c,target,.06);const hover=mix(c,dark?[255,255,255]:[0,0,0],.12),pressed=mix(c,[0,0,0],.18),surface=dark?[36,47,64]:[255,255,255];return {accent:hex(c),hover:hex(hover),pressed:hex(pressed),on:dark?'#142034':'#ffffff',soft:hex(mix(surface,c,.18)),selectedHover:hex(mix(surface,c,.16)),selectedPressed:hex(mix(surface,c,.20)),rgb:c.map(Math.round).join(',')};}
 function apply(){const body=document.body,style=body.style,dark=body.classList.contains('dark');
  body.toggleAttribute('data-person-background',!!config.background);if(config.background)style.setProperty('--personal-background','url("'+config.background+'")');else style.removeProperty('--personal-background');
  body.toggleAttribute('data-person-accent',!!config.accent);if(config.accent){const p=palette(config.accent,dark);Object.entries(p).forEach(([key,value])=>style.setProperty('--personal-'+key,value))}
  tiers.forEach(k=>{body.toggleAttribute('data-person-'+k,!!config[k]);if(config[k]){style.setProperty('--personal-'+k+'-blur',config[k].blur+'px');style.setProperty('--personal-'+k+'-alpha',config[k].opacity/100)}});
 }
 function save(next){next=normalize(next);try{AppStorage.setItem(KEY,JSON.stringify(next));config=next;persisted=next;apply();return true}catch{config=persisted;apply();toast(text('error'));return false}}
 function reset(key){imageGeneration++;const next={...config};if(key)delete next[key];else Object.keys(next).forEach(k=>delete next[k]);return save(next)}
 function settings(){const section=document.createElement('section');section.className='personalization-settings';
  section.innerHTML='<div class="personalization-heading"><h3>'+text('title')+'</h3><button type="button" id="personalResetAll">'+text('all')+'</button></div><p>'+text('help')+'</p><div class="personalization-row"><div><h4>'+text('background')+'</h4><p>'+text('backgroundHelp')+'</p><p id="personalBackgroundStatus" role="status"></p></div><div class="personalization-actions"><button type="button" id="personalChoose">'+text('choose')+'</button><button type="button" data-person-reset="background">'+text('reset')+'</button><input type="file" id="personalImage" accept="image/png,image/jpeg,image/webp" hidden></div></div><div class="personalization-row"><div><h4>'+text('accent')+'</h4><p>'+text('accentHelp')+'</p></div><div class="personalization-actions"><input type="color" id="personalAccent" aria-label="'+text('accent')+'"><button type="button" data-person-reset="accent">'+text('reset')+'</button></div></div>'+tiers.map(k=>'<fieldset class="personalization-material" aria-labelledby="personal-'+k+'-title"><h4 id="personal-'+k+'-title">'+text(k)+'</h4><p>'+text(k+'Help')+'</p><div class="personalization-sliders">'+['blur','opacity'].map(type=>'<label for="personal-'+k+'-'+type+'">'+text(type)+' <output id="personal-'+k+'-'+type+'-value" for="personal-'+k+'-'+type+'"></output><input type="range" id="personal-'+k+'-'+type+'" data-person-tier="'+k+'" data-person-type="'+type+'" min="'+(type==='blur'?0:40)+'" max="'+(type==='blur'?30:100)+'" step="1"></label>').join('')+'</div><button type="button" data-person-reset="'+k+'">'+text('reset')+'</button></fieldset>').join('');
  $('#extraSection .settings-panel').append(section);
  function refresh(){section.querySelector('#personalAccent').value=config.accent||'#244a81';section.querySelector('#personalBackgroundStatus').textContent=text(config.background?'ready':'none');section.querySelectorAll('[data-person-tier]').forEach(el=>{const k=el.dataset.personTier,type=el.dataset.personType,value=(config[k]||defaults[k])[type];el.value=value;section.querySelector('#'+el.id+'-value').textContent=value+(type==='blur'?' px':'%')})}
  section.querySelectorAll('[data-person-reset]').forEach(button=>button.onclick=()=>{if(reset(button.dataset.personReset))refresh()});
  section.querySelector('#personalResetAll').onclick=()=>{if(reset())refresh()};
  section.querySelector('#personalAccent').oninput=e=>{config=normalize({...config,accent:e.target.value});apply()};section.querySelector('#personalAccent').onchange=()=>{if(!save(config))refresh()};
  section.querySelectorAll('[data-person-tier]').forEach(el=>el.oninput=()=>{const k=el.dataset.personTier,type=el.dataset.personType,next={...config,[k]:{...(config[k]||defaults[k]),[type]:Number(el.value)}};config=normalize(next);apply();section.querySelector('#'+el.id+'-value').textContent=el.value+(type==='blur'?' px':'%')});
  section.querySelectorAll('[data-person-tier]').forEach(el=>el.onchange=()=>{if(!save(config))refresh()});
  const fileInput=section.querySelector('#personalImage');section.querySelector('#personalChoose').onclick=()=>fileInput.click();
  fileInput.onchange=async()=>{const file=fileInput.files[0];fileInput.value='';if(!file)return;const generation=++imageGeneration;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>15*1024*1024){toast(text('imageError'));return}try{const background=await imageData(file);if(generation!==imageGeneration)return;if(save({...config,background}))refresh()}catch{if(generation===imageGeneration)toast(text('loadError'))}};
  refresh();
 }
 async function imageData(file,{size=2560,square=false}={}){const url=URL.createObjectURL(file);try{const image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=reject;image.src=url});if(!image.naturalWidth||!image.naturalHeight||image.naturalWidth*image.naturalHeight>80000000)throw Error('Image too large');const ratio=Math.min(1,size/Math.max(image.naturalWidth,image.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.naturalWidth*ratio));canvas.height=Math.max(1,Math.round(image.naturalHeight*ratio));const ctx=canvas.getContext('2d');ctx.fillStyle='#f3f5f8';ctx.fillRect(0,0,canvas.width,canvas.height);if(square){const side=Math.min(image.naturalWidth,image.naturalHeight);canvas.width=canvas.height=size;ctx.fillStyle='#f3f5f8';ctx.fillRect(0,0,size,size);ctx.drawImage(image,(image.naturalWidth-side)/2,(image.naturalHeight-side)/2,side,side,0,0,size,size)}else ctx.drawImage(image,0,0,canvas.width,canvas.height);let data=canvas.toDataURL('image/jpeg',.82);if(data.length>3000000)data=canvas.toDataURL('image/jpeg',.6);if(data.length>3000000)throw Error('Image too large');canvas.width=canvas.height=0;return data}finally{URL.revokeObjectURL(url)}}
 const baseSettings=renderSettings;renderSettings=function(){baseSettings();settings()};
 apply();return {apply,normalize,palette,save,reset,imageData,get:()=>JSON.parse(JSON.stringify(config)),defaults};
})();
